// ─── File: AccessControlDemo.java ───
package com.bank.access;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class AccessControlDemo {
    private static final Logger log = Logger.getLogger(AccessControlDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Subject priya = new Subject("priya", Set.of("TELLER"), "MUMBAI", new BigDecimal("500000"));

        RbacPolicy rbac = new RbacPolicy();
        log.info(() -> "RBAC: priya can approve transfers? " + rbac.canApproveTransfer(priya));
        log.info(() -> "RBAC: priya can close accounts? " + rbac.canCloseAccount(priya));

        AbacPolicy abac = new AbacPolicy(9, 17);
        // In-branch, daytime, under limit -> allowed
        TransferRequest t1 = new TransferRequest("SAV2001", "MUMBAI", new BigDecimal("50000"), 11);
        log.info(() -> "ABAC: in-branch daytime 50k -> " + abac.canApprove(priya, t1));

        // Out-of-branch -> denied
        TransferRequest t2 = new TransferRequest("SAV2001", "DELHI", new BigDecimal("50000"), 11);
        log.warning(() -> "ABAC: out-of-branch -> " + abac.canApprove(priya, t2));

        // After hours -> denied
        TransferRequest t3 = new TransferRequest("SAV2001", "MUMBAI", new BigDecimal("50000"), 20);
        log.warning(() -> "ABAC: after-hours -> " + abac.canApprove(priya, t3));
    }
}

// ─── Would be in Subject.java ───
class Subject {
    final String username;
    final Set<String> roles;
    final String branch;
    final BigDecimal dailyLimit;
    Subject(String u, Set<String> r, String b, BigDecimal l) {
        username = u; roles = r; branch = b; dailyLimit = l;
    }
    boolean hasRole(String role) { return roles.contains(role); }
}

// ─── Would be in TransferRequest.java ───
class TransferRequest {
    final String accountId;
    final String accountBranch;
    final BigDecimal amount;
    final int hourOfDay;
    TransferRequest(String a, String br, BigDecimal amt, int hr) {
        accountId = a; accountBranch = br; amount = amt; hourOfDay = hr;
    }
}

// ─── Would be in RbacPolicy.java ───
class RbacPolicy {
    boolean canApproveTransfer(Subject s) { return s.hasRole("TELLER") || s.hasRole("ADMIN"); }
    boolean canCloseAccount(Subject s)    { return s.hasRole("ADMIN"); }
}

// ─── Would be in AbacPolicy.java ───
class AbacPolicy {
    private final int startHour, endHour;
    AbacPolicy(int startHour, int endHour) { this.startHour = startHour; this.endHour = endHour; }

    boolean canApprove(Subject s, TransferRequest t) {
        boolean sameBranch = s.branch.equals(t.accountBranch);          // resource attribute
        boolean businessHours = t.hourOfDay >= startHour && t.hourOfDay < endHour; // environment
        boolean underLimit = t.amount.compareTo(s.dailyLimit) <= 0;      // subject attribute
        return s.hasRole("TELLER") && sameBranch && businessHours && underLimit;
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
            r.getMillis(), r.getLevel().getName(),
            r.getSourceClassName() == null ? "Unknown"
                : r.getSourceClassName().substring(r.getSourceClassName().lastIndexOf('.') + 1),
            r.getMessage());
    }
}
